    Args:
        *args (str) : URL components to join

    Returns:
        str : joined URL

    """
def urljoin(*args: Any) -> object {
    import from six.moves.urllib.parse { urljoin as sys_urljoin }
    import from functools { reduce }
    return reduce(sys_urljoin, args);
}

